1	/**
2	 * asaas-capture-payment — Captura o hold no Asaas e credita o worker na conclusão do turno.
3	 *
4	 * Fluxo postpago (Slice 2 / ADR-20260622-pagamento-postpago):
5	 *  Chamado pela empresa na conclusão do turno (espelha asaas-checkout para kind='postpaid').
6	 *  Também pode ser disparado por auto-processamento (cron — R9) após janela de carência.
7	 *
8	 *  Dois caminhos:
9	 *  A) Tem hold ativo (status='authorized'/'postpaid'):
10	 *     → captureAuthorizedPayment no Asaas → capture_escrow_postpago (credita worker).
11	 *  B) Sem hold (charge_on_demand / hold expirado):
12	 *     → charge direta com o token default da empresa → authorize_escrow_postpago + capture_escrow_postpago.
13	 *     (fallback — sem ADR adicional, mesmo gateway Asaas, Article 6 intacto.)
14	 *
15	 * Idempotência:
16	 *  - capture_escrow_postpago usa WHERE status='authorized' → double-capture não duplica crédito.
17	 *  - UNIQUE (wallet_id, reference_id) em wallet_transactions → idempotência do crédito.
18	 *
19	 * Deploy normal (com verify-jwt) — caller é a EMPRESA.
20	 * Article 10: service_role apenas no Deno.
21	 */
22	
23	import { serve } from 'https://deno.land/std@0.168.0/http/server.ts';
24	import { createClient } from 'jsr:@supabase/supabase-js@2';
25	import { getCorsHeaders, ASAAS_API_URL, getAsaasHeaders } from '../_shared/asaas.ts';
26	import { isRateLimited } from '../_shared/rate-limit.ts';
27	
28	serve(async (req) => {
29	  const corsHeaders = getCorsHeaders(req);
30	
31	  if (req.method === 'OPTIONS') {
32	    return new Response('ok', { headers: corsHeaders });
33	  }
34	
35	  try {
36	    const supabaseAdmin = createClient(
37	      Deno.env.get('SUPABASE_URL') ?? '',
38	      Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? ''
39	    );
40	
41	    // --- Auth (caller = empresa) ---
42	    const authHeader = req.headers.get('Authorization');
43	    if (!authHeader) throw new Error('Missing Authorization header');
44	    const token = authHeader.startsWith('Bearer ') ? authHeader.slice(7) : authHeader;
45	    const { data: { user }, error: userError } = await supabaseAdmin.auth.getUser(token);
46	    if (userError || !user) throw new Error('Invalid Token');
47	
48	    if (isRateLimited(user.id, 'capture-payment', 5, 60_000)) {
49	      return new Response(
50	        JSON.stringify({ error: 'Muitas tentativas. Aguarde 1 minuto.' }),
51	        { headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 429 }
52	      );
53	    }
54	
55	    const { jobId, workerId } = await req.json();
56	    if (!jobId || !workerId) throw new Error('jobId e workerId são obrigatórios.');
57	
58	    // --- Verificar que o caller é dono do job ---
59	    const { data: job, error: jobErr } = await supabaseAdmin
60	      .from('jobs')
61	      .select('company_id, budget, title')
62	      .eq('id', jobId)
63	      .maybeSingle();
64	
65	    if (jobErr || !job) throw new Error('Vaga não encontrada.');
66	    if (job.company_id !== user.id) throw new Error('Não autorizado: você não é o dono desta vaga.');
67	
68	    // --- Verificar application concluída ou checkout confirmado ---
69	    const { data: app, error: appErr } = await supabaseAdmin
70	      .from('applications')
71	      .select('worker_id, status, company_checkout_confirmed_at')
72	      .eq('job_id', jobId)
73	      .eq('worker_id', workerId)
74	      .in('status', ['in_progress', 'completed'])
75	      .maybeSingle();
76	
77	    if (appErr || !app) {
78	      throw new Error('Candidatura não encontrada ou trabalho ainda não foi iniciado.');
79	    }
80	    if (app.status !== 'completed' && !app.company_checkout_confirmed_at) {
81	      throw new Error('O trabalho precisa estar concluído antes de liberar o pagamento.');
82	    }
83	
84	    // --- Get-or-create carteira do worker ---
85	    let workerWalletId: string;
86	    const { data: workerWallet } = await supabaseAdmin
87	      .from('wallets')
88	      .select('id')
89	      .eq('user_id', workerId)
90	      .maybeSingle();
91	
92	    if (workerWallet) {
93	      workerWalletId = workerWallet.id;
94	    } else {
95	      const { data: newWallet, error: createErr } = await supabaseAdmin
96	        .from('wallets')
97	        .insert({ user_id: workerId, balance: 0, user_type: 'worker' })
98	        .select('id')
99	        .single();
100	      if (createErr || !newWallet) throw new Error('Falha ao criar carteira do worker.');
101	      workerWalletId = newWallet.id;
102	    }
103	
104	    // --- Buscar escrow postpago 'authorized' ---
105	    const { data: escrow } = await supabaseAdmin
106	      .from('escrow_transactions')
107	      .select('id, asaas_payment_id, amount, status, captured_at')
108	      .eq('job_id', jobId)
109	      .eq('kind', 'postpaid')
110	      .maybeSingle();
111	
112	    // --- Caminho A: tem hold ativo → capturar ---
113	    if (escrow && escrow.status === 'authorized' && escrow.asaas_payment_id) {
114	      const asaasPaymentId: string = escrow.asaas_payment_id;
115	
116	      // captureAuthorizedPayment no Asaas
117	      const captureRes = await fetch(
118	        `${ASAAS_API_URL}/payments/${asaasPaymentId}/captureAuthorizedPayment`,
119	        {
120	          method: 'POST',
121	          headers: getAsaasHeaders(),
122	          body: JSON.stringify({}),
123	        }
124	      );
125	      const captureData = await captureRes.json();
126	
127	      // Tratar hold expirado (fallback charge_on_demand)
128	      const isHoldExpired =
129	        !captureRes.ok &&
130	        (captureData.errors?.[0]?.description?.toLowerCase().includes('expir') ||
131	          captureData.errors?.[0]?.code === 'invalid_action' ||
132	          captureRes.status === 400);
133	
134	      if (isHoldExpired) {
135	        console.warn(
136	          `[capture-payment] Hold expirado (job=${jobId}), executando charge_on_demand.`
137	        );
138	        return await chargeOnDemand(
139	          supabaseAdmin,
140	          jobId,
141	          app.worker_id ?? workerId,
142	          workerWalletId,
143	          job.company_id,
144	          job.budget,
145	          job.title,
146	          req,
147	          corsHeaders
148	        );
149	      }
150	
151	      if (!captureRes.ok) {
152	        throw new Error(
153	          captureData.errors?.[0]?.description ||
154	          captureData.error ||
155	          'Erro ao capturar cobrança no Asaas.'
156	        );
157	      }
158	
159	      // RPC atômica: marca released + credita worker (idempotente por (wallet_id, reference_id))
160	      const { error: rpcErr } = await supabaseAdmin.rpc('capture_escrow_postpago', {
161	        p_job_id: jobId,
162	        p_worker_wallet_id: workerWalletId,
163	      });
164	
165	      if (rpcErr) {
166	        // Erro após captura no Asaas — logar para reconciliação
167	        console.error(
168	          `[capture-payment] RPC capture_escrow_postpago falhou após captura Asaas. ` +
169	          `job=${jobId} asaas_payment_id=${asaasPaymentId}. Erro: ${rpcErr.message}`
170	        );
171	        throw new Error('Falha ao registrar crédito. Pagamento foi capturado — contacte o suporte.');
172	      }
173	
174	      return new Response(
175	        JSON.stringify({ success: true }),
176	        { headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 200 }
177	      );
178	    }
179	
180	    // --- Escrow já capturado/released → idempotente ---
181	    if (escrow && (escrow.status === 'released' || escrow.status === 'captured')) {
182	      return new Response(
183	        JSON.stringify({ success: true, idempotent: true }),
184	        { headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 200 }
185	      );
186	    }
187	
188	    // --- Caminho B: sem hold (charge_on_demand / job postpago sem pré-auth) ---
189	    if (!escrow || escrow.status === 'refunded') {
190	      return await chargeOnDemand(
191	        supabaseAdmin,
192	        jobId,
193	        workerId,
194	        workerWalletId,
195	        job.company_id,
196	        job.budget,
197	        job.title,
198	        req,
199	        corsHeaders
200	      );
201	    }
202	
203	    throw new Error(`Estado de escrow inesperado: ${escrow?.status ?? 'ausente'}.`);
204	  } catch (error: unknown) {
205	    const msg = error instanceof Error ? error.message : 'Erro interno.';
206	    console.error('asaas-capture-payment error:', msg);
207	    return new Response(
208	      JSON.stringify({ error: msg }),
209	      { headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 400 }
210	    );
211	  }
212	});
213	
214	// ---------------------------------------------------------------------------
215	// Charge-on-demand: cobrança direta com token (sem hold prévio).
216	// Usado quando: modo charge_on_demand, hold expirado, ou sem pré-auth disponível.
217	// ---------------------------------------------------------------------------
218	
219	async function chargeOnDemand(
220	  // deno-lint-ignore no-explicit-any
221	  supabaseAdmin: any,
222	  jobId: string,
223	  workerId: string,
224	  workerWalletId: string,
225	  companyUserId: string,
226	  amount: number,
227	  jobTitle: string,
228	  req: Request,
229	  corsHeaders: Record<string, string>
230	): Promise<Response> {
231	  // Buscar token default da empresa
232	  const { data: pm, error: pmErr } = await supabaseAdmin
233	    .from('payment_methods')
234	    .select('asaas_credit_card_token')
235	    .eq('company_id', companyUserId)
236	    .eq('is_default', true)
237	    .maybeSingle();
238	
239	  if (pmErr || !pm) {
240	    throw new Error('Método de pagamento da empresa não encontrado para cobrança direta.');
241	  }
242	
243	  const { data: companyWallet } = await supabaseAdmin
244	    .from('wallets')
245	    .select('asaas_customer_id')
246	    .eq('user_id', companyUserId)
247	    .maybeSingle();
248	
249	  if (!companyWallet?.asaas_customer_id) {
250	    throw new Error('Conta Asaas da empresa não encontrada.');
251	  }
252	
253	  const remoteIp =
254	    req.headers.get('x-forwarded-for')?.split(',')[0]?.trim() ||
255	    req.headers.get('x-real-ip') ||
256	    '0.0.0.0';
257	
258	  const dueDate = new Date();
259	  dueDate.setDate(dueDate.getDate() + 1);
260	
261	  // Cobrança direta (sem authorizeOnly)
262	  const chargeRes = await fetch(`${ASAAS_API_URL}/payments`, {
263	    method: 'POST',
264	    headers: getAsaasHeaders(),
265	    body: JSON.stringify({
266	      customer: companyWallet.asaas_customer_id,
267	      billingType: 'CREDIT_CARD',
268	      value: amount,
269	      dueDate: dueDate.toISOString().split('T')[0],
270	      description: `Pagamento de turno: ${jobTitle}`,
271	      externalReference: jobId,
272	      creditCardToken: pm.asaas_credit_card_token,
273	      remoteIp,
274	    }),
275	  });
276	
277	  const chargeData = await chargeRes.json();
278	  if (!chargeRes.ok) {
279	    throw new Error(
280	      chargeData.errors?.[0]?.description ||
281	      chargeData.error ||
282	      'Erro ao cobrar cartão da empresa.'
283	    );
284	  }
285	
286	  const asaasPaymentId: string = chargeData.id;
287	
288	  // Buscar escrow postpago existente — excluindo 'refunded' (tratado como ausente:
289	  // o hold foi liberado antes da captura, portanto precisamos criar um escrow novo
290	  // com o asaasPaymentId desta cobrança direta antes de capturar).
291	  const { data: escrowExists } = await supabaseAdmin
292	    .from('escrow_transactions')
293	    .select('id')
294	    .eq('job_id', jobId)
295	    .eq('kind', 'postpaid')
296	    .neq('status', 'refunded')
297	    .maybeSingle();
298	
299	  // Se não há escrow capturável (nunca criado ou previamente estornado), criar e capturar
300	  if (!escrowExists) {
301	    // Buscar applicationId para authorize_escrow
302	    const { data: application } = await supabaseAdmin
303	      .from('applications')
304	      .select('id')
305	      .eq('job_id', jobId)
306	      .eq('worker_id', workerId)
307	      .maybeSingle();
308	
309	    const applicationId = application?.id ?? null;
310	
311	    // 1. Authorize (grava o escrow)
312	    const { error: authRpcErr } = await supabaseAdmin.rpc('authorize_escrow_postpago', {
313	      p_job_id: jobId,
314	      p_application_id: applicationId,
315	      p_amount: amount,
316	      p_asaas_payment_id: asaasPaymentId,
317	      p_company_user_id: companyUserId,
318	    });
319	
320	    if (authRpcErr && authRpcErr.code !== '23505') {
321	      console.error(`[charge-on-demand] authorize_escrow_postpago falhou: ${authRpcErr.message}`);
322	      throw new Error('Falha ao registrar escrow após cobrança. Contacte o suporte.');
323	    }
324	  }
325	
326	  // 2. Capture (credita worker — idempotente)
327	  const { error: capRpcErr } = await supabaseAdmin.rpc('capture_escrow_postpago', {
328	    p_job_id: jobId,
329	    p_worker_wallet_id: workerWalletId,
330	  });
331	
332	  if (capRpcErr) {
333	    console.error(
334	      `[charge-on-demand] capture_escrow_postpago falhou após cobrança Asaas. ` +
335	      `job=${jobId} payment=${asaasPaymentId}. Erro: ${capRpcErr.message}`
336	    );
337	    throw new Error('Falha ao registrar crédito após cobrança. Contacte o suporte.');
338	  }
339	
340	  return new Response(
341	    JSON.stringify({ success: true, chargeOnDemand: true }),
342	    { headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 200 }
343	  );
344	}
345

1	/**
2	 * asaas-authorize-payment — Pré-autoriza (hold) o cartão da empresa no aceite do convite.
3	 *
4	 * Fluxo postpago (Slice 2 / ADR-20260622-pagamento-postpago):
5	 *  Chamado pelo ShiftInviteService.respondToInvite('accepted') após o status da application
6	 *  mudar para 'hired'. Cria o hold (authorizeOnly:true) no Asaas e grava o escrow 'authorized'
7	 *  no DB via RPC atômica authorize_escrow_postpago.
8	 *
9	 * Modo controlado por env ASAAS_POSTPAGO_MODE:
10	 *  - 'authorize' (default)    : fluxo normal pré-auth → capture.
11	 *  - 'charge_on_demand'       : pula a pré-auth; a captura acontece na conclusão. Neste caso
12	 *                               a função retorna success sem criar hold nem chamar a RPC.
13	 *
14	 * Idempotência:
15	 *  - idx_escrow_unique_asaas_payment (UNIQUE asaas_payment_id): reprocesso não cria 2º escrow.
16	 *  - 23505 do índice idx_escrow_one_authorized_per_job → tratar como já-autorizado.
17	 *
18	 * Deploy normal (com verify-jwt) — caller é o WORKER autenticado.
19	 * Article 10: service_role apenas no Deno.
20	 */
21	
22	import { serve } from 'https://deno.land/std@0.168.0/http/server.ts';
23	import { createClient } from 'jsr:@supabase/supabase-js@2';
24	import { getCorsHeaders, ASAAS_API_URL, getAsaasHeaders } from '../_shared/asaas.ts';
25	import { isRateLimited } from '../_shared/rate-limit.ts';
26	
27	serve(async (req) => {
28	  const corsHeaders = getCorsHeaders(req);
29	
30	  if (req.method === 'OPTIONS') {
31	    return new Response('ok', { headers: corsHeaders });
32	  }
33	
34	  try {
35	    const supabaseAdmin = createClient(
36	      Deno.env.get('SUPABASE_URL') ?? '',
37	      Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? ''
38	    );
39	
40	    // --- Auth (caller = worker) ---
41	    const authHeader = req.headers.get('Authorization');
42	    if (!authHeader) throw new Error('Missing Authorization header');
43	    const token = authHeader.startsWith('Bearer ') ? authHeader.slice(7) : authHeader;
44	    const { data: { user }, error: userError } = await supabaseAdmin.auth.getUser(token);
45	    if (userError || !user) throw new Error('Invalid Token');
46	
47	    if (isRateLimited(user.id, 'authorize-payment', 5, 60_000)) {
48	      return new Response(
49	        JSON.stringify({ error: 'Muitas tentativas. Aguarde 1 minuto.' }),
50	        { headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 429 }
51	      );
52	    }
53	
54	    const { jobId, applicationId } = await req.json();
55	    if (!jobId || !applicationId) throw new Error('jobId e applicationId são obrigatórios.');
56	
57	    // --- Verificar que o caller é o worker desta application ---
58	    const { data: app, error: appErr } = await supabaseAdmin
59	      .from('applications')
60	      .select('id, worker_id, job_id, status, invited_by_company_at')
61	      .eq('id', applicationId)
62	      .maybeSingle();
63	
64	    if (appErr || !app) throw new Error('Candidatura não encontrada.');
65	    if (app.worker_id !== user.id) throw new Error('Não autorizado: esta candidatura não é sua.');
66	    if (app.job_id !== jobId) throw new Error('jobId não corresponde à candidatura.');
67	    if (!app.invited_by_company_at) {
68	      throw new Error('Esta candidatura não é um convite push (invited_by_company_at ausente).');
69	    }
70	    if (app.status !== 'hired') {
71	      throw new Error(
72	        `Status da candidatura deve ser 'hired' para autorizar pagamento, mas é '${app.status}'.`
73	      );
74	    }
75	
76	    // --- Verificar se já existe escrow postpago para este job (idempotência + proteção) ---
77	    // Busca SEM filtro de status: trata cada estado de forma explícita para não criar
78	    // holds adicionais no cartão da empresa sem novo consentimento.
79	    const { data: existingEscrow } = await supabaseAdmin
80	      .from('escrow_transactions')
81	      .select('id, asaas_payment_id, status')
82	      .eq('job_id', jobId)
83	      .eq('kind', 'postpaid')
84	      .maybeSingle();
85	
86	    if (existingEscrow) {
87	      if (existingEscrow.status === 'authorized') {
88	        // Já autorizado — idempotência: retorna o existente sem criar 2º hold
89	        return new Response(
90	          JSON.stringify({
91	            success: true,
92	            escrowId: existingEscrow.id,
93	            asaasPaymentId: existingEscrow.asaas_payment_id,
94	            status: 'authorized',
95	            idempotent: true,
96	          }),
97	          { headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 200 }
98	        );
99	      }
100	
101	      // Estado terminal: refunded / captured / released.
102	      // Não recriar hold sem novo convite/consentimento da empresa. Rejeitar explicitamente.
103	      return new Response(
104	        JSON.stringify({
105	          error:
106	            `Não é possível criar novo hold: o escrow deste turno já está em estado '${existingEscrow.status}'. ` +
107	            'Para um novo comprometimento de pagamento, a empresa deve emitir um novo convite.',
108	        }),
109	        { headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 409 }
110	      );
111	    }
112	
113	    // --- Modo: 'authorize' | 'charge_on_demand' ---
114	    const mode = Deno.env.get('ASAAS_POSTPAGO_MODE') ?? 'authorize';
115	
116	    if (mode === 'charge_on_demand') {
117	      // Pula a pré-auth; captura será feita na conclusão. Retorna success sem escrow.
118	      console.log(`[authorize-payment] charge_on_demand mode: skip hold for job=${jobId}`);
119	      return new Response(
120	        JSON.stringify({ success: true, status: 'charge_on_demand', mode }),
121	        { headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 200 }
122	      );
123	    }
124	
125	    // --- Buscar dados do job (valor + company_id) ---
126	    const { data: job, error: jobErr } = await supabaseAdmin
127	      .from('jobs')
128	      .select('company_id, budget, title')
129	      .eq('id', jobId)
130	      .maybeSingle();
131	
132	    if (jobErr || !job) throw new Error('Vaga não encontrada.');
133	    const amount: number = job.budget;
134	    if (!amount || amount <= 0) throw new Error('Budget da vaga inválido para pré-autorização.');
135	
136	    const companyUserId: string = job.company_id;
137	
138	    // --- Buscar método de pagamento default da empresa ---
139	    const { data: pm, error: pmErr } = await supabaseAdmin
140	      .from('payment_methods')
141	      .select('asaas_credit_card_token, brand, last4')
142	      .eq('company_id', companyUserId)
143	      .eq('is_default', true)
144	      .maybeSingle();
145	
146	    if (pmErr || !pm) {
147	      throw new Error(
148	        'A empresa não possui método de pagamento cadastrado. ' +
149	        'Solicite ao operador que cadastre um cartão antes de aceitar convites.'
150	      );
151	    }
152	
153	    // --- Buscar asaas_customer_id da empresa ---
154	    const { data: companyWallet, error: cwErr } = await supabaseAdmin
155	      .from('wallets')
156	      .select('asaas_customer_id')
157	      .eq('user_id', companyUserId)
158	      .maybeSingle();
159	
160	    if (cwErr || !companyWallet?.asaas_customer_id) {
161	      throw new Error('Conta de pagamento da empresa não encontrada no Asaas.');
162	    }
163	
164	    // --- remoteIp (exigido pelo Asaas para cobrança com cartão) ---
165	    const remoteIp =
166	      req.headers.get('x-forwarded-for')?.split(',')[0]?.trim() ||
167	      req.headers.get('x-real-ip') ||
168	      '0.0.0.0';
169	
170	    // dueDate = hoje + 1 dia (mínimo exigido pelo Asaas)
171	    const dueDate = new Date();
172	    dueDate.setDate(dueDate.getDate() + 1);
173	    const dueDateStr = dueDate.toISOString().split('T')[0];
174	
175	    // --- POST /v3/payments com authorizeOnly:true ---
176	    const paymentRes = await fetch(`${ASAAS_API_URL}/payments`, {
177	      method: 'POST',
178	      headers: getAsaasHeaders(),
179	      body: JSON.stringify({
180	        customer: companyWallet.asaas_customer_id,
181	        billingType: 'CREDIT_CARD',
182	        value: amount,
183	        dueDate: dueDateStr,
184	        description: `Turno reservado: ${job.title}`,
185	        externalReference: jobId,
186	        authorizeOnly: true,
187	        creditCardToken: pm.asaas_credit_card_token,
188	        remoteIp,
189	      }),
190	    });
191	
192	    const paymentData = await paymentRes.json();
193	
194	    // --- Tratar falha: distinguir "pré-auth não habilitada" de recusa de cartão ---
195	    if (!paymentRes.ok) {
196	      const errCode: string = paymentData.errors?.[0]?.code ?? '';
197	      const errMsg: string = paymentData.errors?.[0]?.description || paymentData.error || '';
198	
199	      // Códigos específicos do Asaas que indicam que a funcionalidade de pré-autorização
200	      // não está habilitada na conta (configuração do merchant, não recusa de cartão).
201	      // Referência: documentação Asaas — "authorizeOnly not available for this account".
202	      const PRE_AUTH_UNAVAILABLE_CODES = new Set([
203	        'invalid_action',
204	        'INVALID_ACTION',
205	        'authorize_only_not_available',
206	        'AUTHORIZE_ONLY_NOT_AVAILABLE',
207	      ]);
208	
209	      const isPreAuthDisabled =
210	        PRE_AUTH_UNAVAILABLE_CODES.has(errCode) ||
211	        errMsg.toLowerCase().includes('authorize_only') ||
212	        errMsg.toLowerCase().includes('authorizeonly') ||
213	        errMsg.toLowerCase().includes('pre-authorization not available') ||
214	        errMsg.toLowerCase().includes('pré-autorização não disponível');
215	
216	      if (isPreAuthDisabled) {
217	        console.warn(
218	          `[authorize-payment] Pré-auth não disponível na conta (fallback charge_on_demand): ` +
219	          `code=${errCode} msg=${errMsg}`
220	        );
221	        return new Response(
222	          JSON.stringify({ success: true, status: 'charge_on_demand', fallback: true, reason: errMsg }),
223	          { headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 200 }
224	        );
225	      }
226	
227	      // Qualquer outro erro (incluindo recusa de cartão) deve ser surfaced — não engolir.
228	      console.error(
229	        `[authorize-payment] Falha na pré-autorização: code=${errCode} status=${paymentRes.status} msg=${errMsg}`
230	      );
231	      throw new Error(errMsg || 'Erro ao criar pré-autorização no Asaas.');
232	    }
233	
234	    const asaasPaymentId: string = paymentData.id;
235	    if (!asaasPaymentId) throw new Error('Asaas não retornou o id da cobrança.');
236	
237	    // Status esperado: AUTHORIZED. Se não, logar mas prosseguir (Asaas pode retornar PENDING transitório)
238	    if (paymentData.status && paymentData.status !== 'AUTHORIZED') {
239	      console.warn(
240	        `[authorize-payment] Status Asaas inesperado: ${paymentData.status} para payment=${asaasPaymentId}`
241	      );
242	    }
243	
244	    // --- Gravar escrow 'authorized'/'postpaid' no DB (RPC atômica) ---
245	    const { data: escrowId, error: rpcErr } = await supabaseAdmin.rpc(
246	      'authorize_escrow_postpago',
247	      {
248	        p_job_id: jobId,
249	        p_application_id: applicationId,
250	        p_amount: amount,
251	        p_asaas_payment_id: asaasPaymentId,
252	        p_company_user_id: companyUserId,
253	      }
254	    );
255	
256	    if (rpcErr) {
257	      // 23505 = único violado (hold duplicado) — tratar como idempotente
258	      if (rpcErr.code === '23505') {
259	        console.warn(`[authorize-payment] Escrow duplicado (23505), tratando como idempotente.`);
260	        return new Response(
261	          JSON.stringify({ success: true, asaasPaymentId, status: 'authorized', idempotent: true }),
262	          { headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 200 }
263	        );
264	      }
265	      // RPC falhou após criar o hold no Asaas — logar para reconciliação manual
266	      console.error(
267	        `[authorize-payment] RPC authorize_escrow_postpago falhou após hold criado. ` +
268	        `asaas_payment_id=${asaasPaymentId} job=${jobId}. Erro: ${rpcErr.message}`
269	      );
270	      throw new Error('Falha ao registrar escrow. O hold foi criado no Asaas — contacte o suporte.');
271	    }
272	
273	    return new Response(
274	      JSON.stringify({
275	        success: true,
276	        escrowId,
277	        asaasPaymentId,
278	        status: 'authorized',
279	      }),
280	      { headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 200 }
281	    );
282	  } catch (error: unknown) {
283	    const msg = error instanceof Error ? error.message : 'Erro interno.';
284	    console.error('asaas-authorize-payment error:', msg);
285	    return new Response(
286	      JSON.stringify({ error: msg }),
287	      { headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 400 }
288	    );
289	  }
290	});
