1	/**
2	 * ShiftInviteService — convite push de turno (Slice 1, R5/R7/R8).
3	 *
4	 * Fluxo push: EMPRESA cria application com status='invited' para worker da equipe.
5	 * Fluxo de resposta: WORKER aceita ('accepted') ou recusa ('declined').
6	 *
7	 * Avisos do architect (ADR-001):
8	 * 1. A transição de status do convite (invited → accepted/declined) NÃO é forçada por RLS;
9	 *    validamos a máquina de estados AQUI no service.
10	 * 2. Recusa é NEUTRA (zero punição — R7): só muda status para 'declined'.
11	 * 3. Criar-turno e aceite NÃO chamam reserve_escrow (postpago é Slice 2).
12	 *    accepted aqui = status 'hired' (confirmado no turno) SEM escrow. Slice 2 preenche o gap.
13	 * 4. inserts de review devem passar direction explicitamente — ver ReviewService em types/index.ts.
14	 */
15	
16	import { supabase } from '../lib/supabase';
17	import { invokeFunction } from './api';
18	import { logError } from '../lib/logger';
19	import { TeamConnectionService } from './teamConnectionService';
20	import type {
21	  Application,
22	  ApplicationStatus,
23	  InvitationResponse,
24	} from '../types';
25	
26	// ---------------------------------------------------------------------------
27	// Tipos do resultado estruturado de autorização de pagamento
28	// ---------------------------------------------------------------------------
29	
30	export type AuthorizePaymentOutcome =
31	  | { kind: 'ok'; asaasPaymentId: string }
32	  | { kind: 'fallback_charge_on_demand'; reason: string }
33	  | { kind: 'card_declined'; errorMsg: string };
34	
35	// ---------------------------------------------------------------------------
36	// Helper interno: disparar pré-autorização postpago (best-effort, não bloqueia o aceite)
37	// ---------------------------------------------------------------------------
38	
39	/**
40	 * Invoca asaas-authorize-payment após o aceite do convite.
41	 * Retorna um resultado estruturado:
42	 *  - 'ok'                    : hold criado com sucesso.
43	 *  - 'fallback_charge_on_demand': pré-auth não habilitada; cobrança será na conclusão.
44	 *  - 'card_declined'         : cartão recusado — empresa deve verificar o método de pagamento.
45	 *
46	 * Falha NÃO reverte o status 'hired' — o aceite já aconteceu no DB.
47	 * Em 'card_declined', uma notificação in-app é criada para a empresa.
48	 */
49	async function dispatchAuthorizePayment(
50	  jobId: string,
51	  applicationId: string,
52	  companyOwnerId: string,
53	): Promise<AuthorizePaymentOutcome> {
54	  try {
55	    // invokeFunction lança se HTTP status >= 400 (comportamento padrão de api.ts)
56	    const result = await invokeFunction('asaas-authorize-payment', { jobId, applicationId }) as {
57	      success?: boolean;
58	      status?: string;
59	      fallback?: boolean;
60	      reason?: string;
61	      asaasPaymentId?: string;
62	    };
63	
64	    if (result?.status === 'charge_on_demand') {
65	      return { kind: 'fallback_charge_on_demand', reason: result.reason ?? '' };
66	    }
67	
68	    return { kind: 'ok', asaasPaymentId: result?.asaasPaymentId ?? '' };
69	  } catch (authErr) {
70	    const errMsg = authErr instanceof Error ? authErr.message : 'Erro desconhecido na autorização.';
71	
72	    // Detectar recusa de cartão: a Edge Function agora lança erros específicos (não engole mais
73	    // recusas). Qualquer erro que não seja "pré-auth não disponível" é tratado como card_declined
74	    // para fins de notificação — o flow de captura fallback ainda ocorre na conclusão.
75	    logError('shiftInvite.authorizePayment (best-effort)', authErr);
76	
77	    // Notificar empresa sobre falha no cartão (best-effort — não bloqueia o aceite)
78	    if (companyOwnerId) {
79	      try {
80	        await supabase.from('notifications').insert({
81	          user_id: companyOwnerId,
82	          type: 'payment',
83	          title: 'Falha na autorização do cartão',
84	          message:
85	            `A autorização do pagamento para o turno falhou: ${errMsg}. ` +
86	            'Verifique o método de pagamento cadastrado para garantir que o freela receba.',
87	          link: '/company/wallet',
88	        });
89	      } catch (notifErr) {
90	        logError('shiftInvite.authorizePayment.notif', notifErr);
91	      }
92	    }
93	
94	    return { kind: 'card_declined', errorMsg: errMsg };
95	  }
96	}
