98	// ---------------------------------------------------------------------------
99	// Tipos de parâmetros e resultado
100	// ---------------------------------------------------------------------------
101	
102	/** Janela de expiração do convite em horas (R8). Default = 48h. */
103	const DEFAULT_INVITE_EXPIRY_HOURS = 48;
104	
105	export interface InviteWorkerToShiftOptions {
106	  /** Horas até o convite expirar (default: 48). */
107	  expiresInHours?: number;
108	  /** Mensagem personalizada para a notificação (opcional). */
109	  message?: string;
110	}
111	
112	export interface InviteWorkerResult {
113	  application: Application | null;
114	  error?: string;
115	  /** true quando já existe um convite pendente (idempotência). */
116	  alreadyInvited?: boolean;
117	}
118	
119	export interface RespondToInviteResult {
120	  success: boolean;
121	  error?: string;
122	}
123	
124	// ---------------------------------------------------------------------------
125	// Helpers internos
126	// ---------------------------------------------------------------------------
127	
128	/** Obtém o company_id da sessão autenticada (empresa). */
129	async function getAuthCompanyId(): Promise<string> {
130	  const {
131	    data: { user },
132	  } = await supabase.auth.getUser();
133	  if (!user) throw new Error('Sessão expirada. Faça login novamente.');
134	
135	  const { data: company, error } = await supabase
136	    .from('companies')
137	    .select('id')
138	    .eq('owner_id', user.id)
139	    .maybeSingle();
140	
141	  if (error) throw error;
142	  if (!company) throw new Error('Perfil de empresa não encontrado.');
143	
144	  return company.id as string;
145	}
146	
147	/** Calcula timestamp de expiração. */
148	function calcExpiry(hours: number): string {
149	  const d = new Date();
150	  d.setHours(d.getHours() + hours);
151	  return d.toISOString();
152	}
