1	-- Migration: Security hardening for checkout/escrow flow
2	-- Fixes critical vulnerabilities in RLS policies, adds column-level validation trigger
3	-- Prevents: workers faking company confirmations, direct balance manipulation,
4	-- unauthorized escrow operations, status manipulation, schema poisoning
5	
6	-- =============================================
7	-- 1. APPLICATIONS: Replace permissive UPDATE policy with role-separated policies
8	--    + BEFORE UPDATE trigger for column-level validation (uses OLD/NEW directly)
9	-- =============================================
10	
11	-- Drop the overly permissive policy
12	DROP POLICY IF EXISTS "Participants can update applications" ON applications;
13	
14	-- Worker RLS: can only see/update rows where they are the worker
15	CREATE POLICY "Workers can update their own application fields" ON applications
16	    FOR UPDATE TO authenticated
17	    USING (worker_id = auth.uid())
18	    WITH CHECK (worker_id = auth.uid());
19	
20	-- Company RLS: can only see/update rows for their jobs
21	CREATE POLICY "Companies can update their job application fields" ON applications
22	    FOR UPDATE TO authenticated
23	    USING (job_id IN (SELECT id FROM jobs WHERE company_id = auth.uid()))
24	    WITH CHECK (job_id IN (SELECT id FROM jobs WHERE company_id = auth.uid()));
25	
26	-- Column-level validation trigger (best practice: direct OLD/NEW access, no self-referencing subqueries)
27	-- SET search_path prevents schema poisoning attacks on SECURITY DEFINER functions
28	CREATE OR REPLACE FUNCTION validate_application_update()
29	RETURNS TRIGGER
30	LANGUAGE plpgsql
31	SECURITY DEFINER
32	SET search_path = public
33	AS $$
34	DECLARE
35	    v_is_worker BOOLEAN;
36	    v_is_company BOOLEAN;
37	BEGIN
38	    -- Bypass for service_role / internal operations (triggers, RPCs)
39	    -- auth.uid() is NULL for service_role and trigger contexts
40	    IF auth.uid() IS NULL THEN
41	        RETURN NEW;
42	    END IF;
43	
44	    v_is_worker := (NEW.worker_id = auth.uid());
45	    v_is_company := EXISTS(SELECT 1 FROM jobs WHERE id = NEW.job_id AND company_id = auth.uid());
46	
47	    -- === IMMUTABLE FIELDS (neither role can change) ===
48	    IF NEW.worker_id IS DISTINCT FROM OLD.worker_id THEN
49	        RAISE EXCEPTION 'Nao e permitido alterar o worker_id';
50	    END IF;
51	    IF NEW.job_id IS DISTINCT FROM OLD.job_id THEN
52	        RAISE EXCEPTION 'Nao e permitido alterar o job_id';
53	    END IF;
54	
55	    -- === WORKER RESTRICTIONS ===
56	    IF v_is_worker THEN
57	        -- Worker CANNOT change company confirmation columns
58	        IF NEW.company_checkin_confirmed_at IS DISTINCT FROM OLD.company_checkin_confirmed_at THEN
59	            RAISE EXCEPTION 'Worker nao pode alterar confirmacao da empresa (checkin)';
60	        END IF;
61	        IF NEW.company_checkout_confirmed_at IS DISTINCT FROM OLD.company_checkout_confirmed_at THEN
62	            RAISE EXCEPTION 'Worker nao pode alterar confirmacao da empresa (checkout)';
63	        END IF;
64	        -- Worker CANNOT set status to 'completed' (only company can finalize)
65	        IF NEW.status = 'completed' AND OLD.status != 'completed' THEN
66	            RAISE EXCEPTION 'Apenas a empresa pode finalizar o trabalho';
67	        END IF;
68	        -- Worker CANNOT set status to 'approved', 'rejected', or 'hired' (company decisions)
69	        IF NEW.status IN ('approved', 'rejected', 'hired') AND OLD.status NOT IN ('approved', 'rejected', 'hired') THEN
70	            RAISE EXCEPTION 'Apenas a empresa pode aprovar, rejeitar ou contratar';
71	        END IF;
72	    END IF;
73	
74	    -- === COMPANY RESTRICTIONS ===
75	    IF v_is_company THEN
76	        -- Company CANNOT change worker check-in/check-out columns
77	        IF NEW.worker_checkin_at IS DISTINCT FROM OLD.worker_checkin_at THEN
78	            RAISE EXCEPTION 'Empresa nao pode alterar checkin do worker';
79	        END IF;
80	        IF NEW.worker_checkout_at IS DISTINCT FROM OLD.worker_checkout_at THEN
81	            RAISE EXCEPTION 'Empresa nao pode alterar checkout do worker';
82	        END IF;
83	    END IF;
84	
85	    -- If caller is neither worker nor company, block entirely
86	    IF NOT v_is_worker AND NOT v_is_company THEN
87	        RAISE EXCEPTION 'Usuario nao autorizado a atualizar esta candidatura';
88	    END IF;
89	
90	    RETURN NEW;
91	END;
92	$$;
93	
94	DROP TRIGGER IF EXISTS trg_validate_application_update ON applications;
95	CREATE TRIGGER trg_validate_application_update
96	    BEFORE UPDATE ON applications
97	    FOR EACH ROW
98	    EXECUTE FUNCTION validate_application_update();
