195	-- 5b. reserve_escrow: validate caller identity + job ownership
196	CREATE OR REPLACE FUNCTION reserve_escrow(
197	    p_job_id UUID,
198	    p_amount DECIMAL,
199	    p_company_user_id UUID
200	)
201	RETURNS UUID
202	LANGUAGE plpgsql
203	SECURITY DEFINER
204	SET search_path = public
205	AS $$
206	DECLARE
207	    v_wallet_id UUID;
208	    v_balance DECIMAL;
209	    v_escrow_id UUID;
210	BEGIN
211	    -- SECURITY: Authenticated users can only reserve for themselves
212	    IF auth.uid() IS NOT NULL AND auth.uid() != p_company_user_id THEN
213	        RAISE EXCEPTION 'Nao autorizado: nao pode reservar escrow para outro usuario';
214	    END IF;
215	
216	    -- SECURITY: Validate caller actually owns the job
217	    IF auth.uid() IS NOT NULL THEN
218	        IF NOT EXISTS(SELECT 1 FROM jobs WHERE id = p_job_id AND company_id = auth.uid()) THEN
219	            RAISE EXCEPTION 'Nao autorizado: voce nao e dono do job %', p_job_id;
220	        END IF;
221	    END IF;
222	
223	    SELECT id, balance INTO v_wallet_id, v_balance
224	    FROM wallets WHERE user_id = p_company_user_id FOR UPDATE;
225	
226	    IF NOT FOUND THEN
227	        RAISE EXCEPTION 'Carteira nao encontrada para usuario: %', p_company_user_id;
228	    END IF;
229	
230	    IF v_balance < p_amount THEN
231	        RAISE EXCEPTION 'Saldo insuficiente. Disponivel: %, Necessario: %', v_balance, p_amount;
232	    END IF;
233	
234	    UPDATE wallets
235	    SET balance = balance - p_amount, updated_at = NOW()
236	    WHERE id = v_wallet_id;
237	
238	    INSERT INTO escrow_transactions(job_id, amount, company_wallet_id, status)
239	    VALUES (p_job_id, p_amount, v_wallet_id, 'reserved')
240	    RETURNING id INTO v_escrow_id;
241	
242	    INSERT INTO wallet_transactions(wallet_id, amount, type, description, reference_id)
243	    VALUES (v_wallet_id, -p_amount, 'escrow_reserve', 'Valor reservado para vaga', p_job_id::TEXT);
244	
245	    RETURN v_escrow_id;
246	END;
247	$$;
