9	CREATE OR REPLACE FUNCTION reserve_escrow(
10	    p_job_id UUID,
11	    p_amount DECIMAL,
12	    p_company_user_id UUID
13	)
14	RETURNS UUID
15	LANGUAGE plpgsql
16	SECURITY DEFINER
17	SET search_path = public
18	AS $$
19	DECLARE
20	    v_wallet_id UUID;
21	    v_balance DECIMAL;
22	    v_escrow_id UUID;
23	BEGIN
24	    -- SECURITY: Authenticated users can only reserve for themselves
25	    IF auth.uid() IS NOT NULL AND auth.uid() != p_company_user_id THEN
26	        RAISE EXCEPTION 'Nao autorizado: nao pode reservar escrow para outro usuario';
27	    END IF;
28	
29	    -- SECURITY: Validate caller actually owns the job
30	    IF auth.uid() IS NOT NULL THEN
31	        IF NOT EXISTS(SELECT 1 FROM jobs WHERE id = p_job_id AND company_id = auth.uid()) THEN
32	            RAISE EXCEPTION 'Nao autorizado: voce nao e dono do job %', p_job_id;
33	        END IF;
34	    END IF;
35	
36	    -- 1. Get company wallet (locked for update to prevent concurrent modifications)
37	    SELECT id, balance INTO v_wallet_id, v_balance
38	    FROM wallets
39	    WHERE user_id = p_company_user_id
40	    FOR UPDATE;
41	
42	    IF NOT FOUND THEN
43	        RAISE EXCEPTION 'Carteira nao encontrada para usuario: %', p_company_user_id;
44	    END IF;
45	
46	    -- 2. Check sufficient balance (only the job amount, no fees)
47	    IF v_balance < p_amount THEN
48	        RAISE EXCEPTION 'Saldo insuficiente. Necessario R$ %', p_amount;
49	    END IF;
50	
51	    -- 3. Atomically deduct ONLY the job amount from balance
52	    UPDATE wallets
53	    SET balance = balance - p_amount,
54	        updated_at = NOW()
55	    WHERE id = v_wallet_id;
56	
57	    -- 4. Create escrow record (no fees stored)
58	    INSERT INTO escrow_transactions(job_id, amount, service_fee, processing_fee, company_wallet_id, status)
59	    VALUES (p_job_id, p_amount, 0, 0, v_wallet_id, 'reserved')
60	    RETURNING id INTO v_escrow_id;
61	
62	    -- 5. Log the escrow reserve transaction
63	    INSERT INTO wallet_transactions(wallet_id, amount, type, description, reference_id)
64	    VALUES (v_wallet_id, -(p_amount), 'escrow_reserve', 'Valor reservado para vaga', p_job_id::TEXT);
65	
66	    RETURN v_escrow_id;
67	END;
68	$$;
