72	-- =============================================
73	-- 2. MODIFY credit_deposit — apply platform fees on deposit for companies
74	--    Workers don't deposit (they earn via escrow release), so no fees for them
75	-- =============================================
76	CREATE OR REPLACE FUNCTION credit_deposit(
77	    p_user_id UUID,
78	    p_amount DECIMAL,
79	    p_payment_id TEXT,
80	    p_description TEXT DEFAULT 'Deposito via Pix'
81	)
82	RETURNS BOOLEAN
83	LANGUAGE plpgsql
84	SECURITY DEFINER
85	SET search_path = public
86	AS $$
87	DECLARE
88	    v_wallet_id UUID;
89	    v_user_type TEXT;
90	    v_service_fee DECIMAL;
91	    v_processing_fee DECIMAL := 4.00;
92	    v_credit_amount DECIMAL;
93	BEGIN
94	    -- Find wallet and user type
95	    SELECT id, user_type INTO v_wallet_id, v_user_type
96	    FROM wallets
97	    WHERE user_id = p_user_id;
98	
99	    IF v_wallet_id IS NULL THEN
100	        RAISE EXCEPTION 'Wallet not found for user: %', p_user_id;
101	    END IF;
102	
103	    -- Calculate fees: only companies pay deposit fees
104	    IF v_user_type = 'company' THEN
105	        v_service_fee := ROUND(p_amount * 0.08, 2);
106	        v_credit_amount := p_amount - v_service_fee - v_processing_fee;
107	        IF v_credit_amount < 0 THEN v_credit_amount := 0; END IF;
108	    ELSE
109	        v_service_fee := 0;
110	        v_processing_fee := 0;
111	        v_credit_amount := p_amount;
112	    END IF;
113	
114	    -- Insert credit transaction (dedup by wallet_id + reference_id unique constraint)
115	    INSERT INTO wallet_transactions(wallet_id, amount, type, description, reference_id)
116	    VALUES (v_wallet_id, v_credit_amount, 'credit', p_description, p_payment_id)
117	    ON CONFLICT (wallet_id, reference_id) WHERE reference_id IS NOT NULL
118	    DO NOTHING;
119	
120	    -- If insert was a no-op (already existed), return false
121	    IF NOT FOUND THEN
122	        RETURN FALSE;
123	    END IF;
124	
125	    -- Credit wallet with net amount (after platform fees)
126	    UPDATE wallets
127	    SET balance = balance + v_credit_amount,
128	        updated_at = NOW()
129	    WHERE id = v_wallet_id;
130	
131	    -- Log platform fee as separate transaction if charged
132	    IF v_service_fee + v_processing_fee > 0 THEN
133	        INSERT INTO wallet_transactions(wallet_id, amount, type, description, reference_id)
134	        VALUES (v_wallet_id, -(v_service_fee + v_processing_fee), 'platform_fee',
135	            'Taxa de servico (8%): R$ ' || v_service_fee::TEXT || ' + Processamento: R$ ' || v_processing_fee::TEXT,
136	            'fee_' || p_payment_id);
137	    END IF;
138	
139	    RETURN TRUE;
140	END;
141	$$;
