17	    v_processing_fee DECIMAL := 4.00;
18	    v_credit_amount DECIMAL;
19	    v_inserted BOOLEAN;
20	BEGIN
21	    -- Find wallet
22	    SELECT id, user_type INTO v_wallet_id, v_user_type
23	    FROM wallets WHERE user_id = p_user_id;
24	
25	    IF v_wallet_id IS NULL THEN
26	        RETURN FALSE;
27	    END IF;
28	
29	    -- Calculate fees (only for companies)
30	    IF v_user_type = 'company' THEN
31	        v_service_fee := ROUND(p_amount * 0.08, 2);
32	        v_credit_amount := p_amount - v_service_fee - v_processing_fee;
33	        IF v_credit_amount < 0 THEN v_credit_amount := 0; END IF;
34	    ELSE
35	        v_service_fee := 0;
36	        v_processing_fee := 0;
37	        v_credit_amount := p_amount;
38	    END IF;
39	
40	    -- Insert transaction (dedup)
41	    INSERT INTO wallet_transactions(wallet_id, amount, type, description, reference_id)
42	    VALUES (v_wallet_id, v_credit_amount, 'credit', p_description, p_payment_id)
43	    ON CONFLICT (wallet_id, reference_id) WHERE reference_id IS NOT NULL DO NOTHING;
44	
45	    GET DIAGNOSTICS v_inserted = ROW_COUNT;
46	    IF NOT v_inserted THEN RETURN FALSE; END IF;
47	
48	    -- Credit wallet
49	    UPDATE wallets SET balance = balance + v_credit_amount WHERE id = v_wallet_id;
50	
51	    -- Log platform fee
52	    IF v_service_fee + v_processing_fee > 0 THEN
53	        INSERT INTO wallet_transactions(wallet_id, amount, type, description, reference_id)
54	        VALUES (v_wallet_id, -(v_service_fee + v_processing_fee), 'platform_fee',
55	            'Worki (8%): R$' || v_service_fee::TEXT || ' + Operador financeiro: R$' || v_processing_fee::TEXT,
56	            'fee_' || p_payment_id);
57	    END IF;
58	
59	    RETURN TRUE;
60	END;
61	$$;
