2	import * as Sentry from '@sentry/react';
3	
4	/**
5	 * Helper para chamar Supabase Edge Functions com error handling padronizado.
6	 * Extrai mensagem de erro do contexto da resposta quando disponivel.
7	 */
8	export async function invokeFunction<T = Record<string, unknown>>(
9	  functionName: string,
10	  body: Record<string, unknown>
11	): Promise<T> {
12	  const { data, error } = await supabase.functions.invoke(functionName, { body });
13	
14	  if (error) {
15	    let msg = error.message;
16	    if (error.context && typeof error.context.json === 'function') {
17	      try {
18	        const errData = await error.context.json();
19	        msg = errData.error || msg;
20	      } catch { /* erro de parse ignorado */ }
21	    }
22	    const err = new Error(msg);
23	    Sentry.captureException(err, { extra: { functionName, body } });
24	    throw err;
25	  }
26	
27	  if (data?.error) {
28	    Sentry.captureMessage(`Edge function ${functionName} returned error: ${data.error}`, 'warning');
29	    throw new Error(data.error);
30	  }
31	
32	  return data as T;
33	}
