1	/**
2	 * asaas-release-hold — Libera o hold no Asaas (cancelamento / no-show antes da captura).
3	 *
4	 * Fluxo postpago (Slice 2 / ADR-20260622-pagamento-postpago):
5	 *  Chamado pela empresa para cancelar o turno ou registrar no-show ANTES da conclusão.
6	 *  Marca o escrow como 'refunded' no DB (RPC release_hold_postpago) e deleta/libera
7	 *  o hold no Asaas (DELETE /v3/payments/{id}).
8	 *
9	 * Idempotência:
10	 *  - release_hold_postpago usa WHERE status='authorized' → não estorna hold já capturado.
11	 *  - Se o escrow já está 'refunded', retorna success sem reprocessar.
12	 *
13	 * Deploy normal (com verify-jwt) — caller é a EMPRESA.
14	 * Article 10: service_role apenas no Deno.
15	 */
16	
17	import { serve } from 'https://deno.land/std@0.168.0/http/server.ts';
18	import { createClient } from 'jsr:@supabase/supabase-js@2';
19	import { getCorsHeaders, ASAAS_API_URL, getAsaasHeaders } from '../_shared/asaas.ts';
20	import { isRateLimited } from '../_shared/rate-limit.ts';
21	
22	serve(async (req) => {
23	  const corsHeaders = getCorsHeaders(req);
24	
25	  if (req.method === 'OPTIONS') {
26	    return new Response('ok', { headers: corsHeaders });
27	  }
28	
29	  try {
30	    const supabaseAdmin = createClient(
31	      Deno.env.get('SUPABASE_URL') ?? '',
32	      Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? ''
33	    );
34	
35	    // --- Auth (caller = empresa) ---
36	    const authHeader = req.headers.get('Authorization');
37	    if (!authHeader) throw new Error('Missing Authorization header');
38	    const token = authHeader.startsWith('Bearer ') ? authHeader.slice(7) : authHeader;
39	    const { data: { user }, error: userError } = await supabaseAdmin.auth.getUser(token);
40	    if (userError || !user) throw new Error('Invalid Token');
41	
42	    if (isRateLimited(user.id, 'release-hold', 5, 60_000)) {
43	      return new Response(
44	        JSON.stringify({ error: 'Muitas tentativas. Aguarde 1 minuto.' }),
45	        { headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 429 }
46	      );
47	    }
48	
49	    const { jobId, reason } = await req.json();
50	    if (!jobId) throw new Error('jobId é obrigatório.');
51	
52	    // --- Verificar que o caller é dono do job ---
53	    const { data: job, error: jobErr } = await supabaseAdmin
54	      .from('jobs')
55	      .select('company_id')
56	      .eq('id', jobId)
57	      .maybeSingle();
58	
59	    if (jobErr || !job) throw new Error('Vaga não encontrada.');
60	    if (job.company_id !== user.id) throw new Error('Não autorizado: você não é o dono desta vaga.');
61	
62	    // --- Verificar estado atual do escrow (idempotência: já refunded = success) ---
63	    const { data: escrow } = await supabaseAdmin
64	      .from('escrow_transactions')
65	      .select('id, status, asaas_payment_id')
66	      .eq('job_id', jobId)
67	      .eq('kind', 'postpaid')
68	      .maybeSingle();
69	
70	    // Sem escrow postpago para este job (job pode ser prepago ou sem hold)
71	    if (!escrow) {
72	      return new Response(
73	        JSON.stringify({ success: true, skipped: true, reason: 'Nenhum escrow postpago encontrado.' }),
74	        { headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 200 }
75	      );
76	    }
77	
78	    // Já liberado — idempotente
79	    if (escrow.status === 'refunded') {
80	      return new Response(
81	        JSON.stringify({ success: true, idempotent: true }),
82	        { headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 200 }
83	      );
84	    }
85	
86	    // Já capturado — não permitir liberar
87	    if (escrow.status === 'released' || escrow.status === 'captured') {
88	      throw new Error(
89	        'O pagamento já foi capturado e não pode ser estornado por esta operação. ' +
90	        'Utilize o processo de reembolso adequado.'
91	      );
92	    }
93	
94	    if (escrow.status !== 'authorized') {
95	      throw new Error(`Estado de escrow inesperado para liberação: '${escrow.status}'.`);
96	    }
97	
98	    // --- RPC: marcar 'refunded' no DB e obter asaas_payment_id ---
99	    const releaseReason = reason || 'Hold liberado (cancelamento/no-show)';
100	    const { data: rpcResult, error: rpcErr } = await supabaseAdmin.rpc(
101	      'release_hold_postpago',
102	      {
103	        p_job_id: jobId,
104	        p_reason: releaseReason,
105	      }
106	    );
107	
108	    if (rpcErr) {
109	      // Se a RPC falhou porque não há hold authorized (race condition — outro processo liberou antes)
110	      if (rpcErr.message?.includes('Nenhum hold autorizado')) {
111	        return new Response(
112	          JSON.stringify({ success: true, idempotent: true }),
113	          { headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 200 }
114	        );
115	      }
116	      throw new Error(rpcErr.message || 'Erro ao liberar escrow no banco de dados.');
117	    }
118	
119	    // A RPC retorna TABLE(escrow_id, asaas_payment_id) — supabase-js retorna array
120	    const row = Array.isArray(rpcResult) ? rpcResult[0] : rpcResult;
121	    const asaasPaymentId: string | null = row?.asaas_payment_id ?? escrow.asaas_payment_id ?? null;
122	
123	    // --- Liberar/deletar o hold no Asaas ---
124	    if (asaasPaymentId) {
125	      const deleteRes = await fetch(`${ASAAS_API_URL}/payments/${asaasPaymentId}`, {
126	        method: 'DELETE',
127	        headers: getAsaasHeaders(),
128	      });
129	
130	      if (!deleteRes.ok) {
131	        const deleteData = await deleteRes.json().catch(() => ({}));
132	        const errMsg: string =
133	          deleteData.errors?.[0]?.description ||
134	          deleteData.error ||
135	          `HTTP ${deleteRes.status}`;
136	
137	        // Hold já expirado no Asaas ou já deletado — não é erro crítico (DB já está correto)
138	        const isAlreadyGone =
139	          deleteRes.status === 404 ||
140	          errMsg.toLowerCase().includes('not found') ||
141	          errMsg.toLowerCase().includes('já cancelad');
142	
143	        if (isAlreadyGone) {
144	          console.warn(
145	            `[release-hold] Hold já removido no Asaas (${errMsg}) — DB marcado como refunded. OK.`
146	          );
147	        } else {
148	          // Logar mas não lançar: o DB está correto (refunded), o hold será expirado naturalmente
149	          console.error(
150	            `[release-hold] Falha ao deletar hold no Asaas: ${errMsg}. ` +
151	            `payment=${asaasPaymentId}. DB correto — hold expirará em 3 dias.`
152	          );
153	        }
154	      }
155	    }
156	
157	    return new Response(
158	      JSON.stringify({ success: true }),
159	      { headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 200 }
160	    );
161	  } catch (error: unknown) {
162	    const msg = error instanceof Error ? error.message : 'Erro interno.';
163	    console.error('asaas-release-hold error:', msg);
164	    return new Response(
165	      JSON.stringify({ error: msg }),
166	      { headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 400 }
167	    );
168	  }
169	});
